<template>
  <div class="har-root">
    <!-- ── LOADING ────────────────────────────────────────────────────── -->
    <div v-if="loading" class="d-flex flex-column align-center justify-center pa-16" style="gap:14px;">
      <v-progress-circular size="36" width="3" indeterminate color="teal darken-1" />
      <span class="caption grey--text">Loading application…</span>
    </div>

    <!-- ── ERROR ──────────────────────────────────────────────────────── -->
    <div v-else-if="error" class="d-flex flex-column align-center pa-16 text-center" style="gap:12px;">
      <v-icon size="48" color="grey lighten-1">mdi-alert-circle-outline</v-icon>
      <div class="subtitle-1 font-weight-bold grey--text text--darken-1">Application not found</div>
      <div class="body-2 grey--text" style="max-width:360px;">{{ error }}</div>
      <v-btn outlined color="teal darken-1" @click="goBack">
        <v-icon left small>mdi-arrow-left</v-icon>Back to Applicants
      </v-btn>
    </div>

    <!-- ── CONTENT ────────────────────────────────────────────────────── -->
    <template v-else-if="appData">
      <!-- ── CONFIRMATION DIALOG ─────────────────────────────────────── -->
      <v-dialog v-model="confirmDialog" max-width="440" persistent>
        <v-card>
          <v-card-title class="text-h6 font-weight-bold">
            {{ confirmTitle }}
          </v-card-title>
          <v-card-text>
            <div style="font-size:14px;color:#44403c;line-height:1.6;">
              {{ confirmMessage }}
            </div>
            <div
              v-if="confirmAction === 'offered' && jobStartDate"
              style="margin-top:10px;font-size:13px;color:#0369a1;background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:8px;padding:8px 12px;"
            >
              Official start date: <strong>{{ fmtDate(jobStartDate) }}</strong>
            </div>
          </v-card-text>
          <v-card-actions>
            <v-spacer></v-spacer>
            <v-btn text @click="confirmDialog = false">Cancel</v-btn>
            <v-btn
              :color="confirmDanger ? 'error' : 'success'"
              depressed
              @click="confirmDecision"
            >
              {{ confirmBtnLabel }}
            </v-btn>
          </v-card-actions>
        </v-card>
      </v-dialog>

      <!-- ── SUPERVISOR DIALOG ──────────────────────────────────────── -->
      <v-dialog v-model="supervisorDialog" max-width="860" scrollable>
        <v-card>
          <v-card-title
            class="primary darken-1 white--text d-flex align-center"
            style="gap:12px;"
          >
            <v-icon color="white">mdi-account-tie</v-icon>
            <span class="font-weight-bold">Select Supervisor</span>
            <v-spacer></v-spacer>
            <v-btn icon small @click="supervisorDialog = false">
              <v-icon color="white">mdi-close</v-icon>
            </v-btn>
          </v-card-title>
          <v-card-text class="pt-4 pb-2">
            <v-row dense>
              <v-col cols="12" sm="6" md="3">
                <v-text-field
                  v-model="supFilter.name"
                  label="Search by Name"
                  dense
                  outlined
                  clearable
                  hide-details
                  prepend-inner-icon="mdi-magnify"
                  @input="debouncedFetchSupervisors"
                />
              </v-col>
              <v-col cols="12" sm="6" md="3">
                <v-text-field
                  v-model="supFilter.position"
                  label="Position / Designation"
                  dense
                  outlined
                  clearable
                  hide-details
                  prepend-inner-icon="mdi-briefcase-outline"
                  @input="debouncedFetchSupervisors"
                />
              </v-col>
              <v-col cols="12" sm="6" md="3">
                <v-autocomplete
                  v-model="supFilter.department"
                  :items="departmentOptions"
                  item-text="display"
                  item-value="code"
                  label="Department"
                  dense
                  outlined
                  clearable
                  hide-details
                  @change="
                    supervisorOptions.page = 1;
                    fetchSupervisors();
                  "
                />
              </v-col>
              <v-col cols="12" sm="6" md="3">
                <v-menu
                  v-model="supFilterTreeOpen"
                  :close-on-content-click="false"
                  offset-y
                  min-width="300"
                >
                  <template v-slot:activator="{ on }">
                    <v-text-field
                      :value="filterTree.displayValue"
                      label="Filter by Location"
                      dense
                      outlined
                      clearable
                      hide-details
                      readonly
                      prepend-inner-icon="mdi-map-marker-outline"
                      v-on="on"
                      @click:clear="clearFilterTree"
                    />
                  </template>
                  <v-card>
                    <v-treeview
                      :active.sync="filterTree.active"
                      :items="filterTree.items"
                      :load-children="fetchFilterChildren"
                      :open.sync="filterTree.open"
                      activatable
                      :multiple-active="false"
                      selection-type="independent"
                      :loading="filterTree.loading"
                      item-key="id"
                      dense
                      hoverable
                      open-on-click
                      style="max-height:280px;overflow-y:auto;"
                    >
                      <template v-slot:label="{ item }">
                        <span style="font-size:13px;">{{ item.name }}</span>
                      </template>
                    </v-treeview>
                  </v-card>
                </v-menu>
              </v-col>
            </v-row>
          </v-card-text>
          <v-card-text class="pa-0">
            <v-data-table
              :headers="supervisorHeaders"
              :items="supervisorItems"
              :loading="loadingSupervisors"
              :server-items-length="supervisorTotal"
              :options.sync="supervisorOptions"
              :footer-props="{ 'items-per-page-options': [10, 20, 50] }"
              item-key="id"
              @click:row="selectSupervisor"
              style="cursor:pointer;"
            >
              <template v-slot:[`item.name`]="{ item }">
                <div class="d-flex align-center" style="gap:10px;">
                  <v-avatar size="28" color="purple lighten-4">
                    <span
                      class="caption indigo--text text--darken-3 font-weight-bold"
                      >{{ getInitials(item.name) }}</span
                    >
                  </v-avatar>
                  <span class="font-weight-medium">{{ item.name }}</span>
                </div>
              </template>
              <template v-slot:[`item._action`]="{ item }">
                <v-btn
                  x-small
                  depressed
                  color="primary"
                  @click.stop="selectSupervisor(item)"
                >
                  Select <v-icon right x-small>mdi-check</v-icon>
                </v-btn>
              </template>
            </v-data-table>
          </v-card-text>
        </v-card>
      </v-dialog>

      <!-- ── HERO ────────────────────────────────────────────────────── -->
      <header class="har-hero">
        <div class="har-hero__bg">
          <div class="har-hero__grid"></div>
          <div class="har-hero__glow"></div>
        </div>
        <div class="har-hero__inner">
          <div class="har-hero__content">
            <div class="har-hero__eyebrow">
              <span class="har-hero__dot"></span>
              HR Application Review
            </div>
            <h1 class="har-hero__title">
              {{
                (appData.advert && appData.advert.title) ||
                  (appData.position && appData.position.title) ||
                  "Application Details"
              }}
            </h1>
            <p
              v-if="appData.advert && appData.advert.description"
              class="har-hero__desc"
            >
              {{ appData.advert.description }}
            </p>
            <div class="har-hero__meta-row">
              <span
                v-if="appData.position && appData.position.department"
                class="har-hero__meta-item"
              >
                <svg
                  width="11"
                  height="11"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                >
                  <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
                  <polyline points="9 22 9 12 15 12 15 22" />
                </svg>
                {{ appData.position.department }}
              </span>
              <span
                v-if="appData.position && appData.position.facility"
                class="har-hero__meta-item"
              >
                <svg
                  width="11"
                  height="11"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                >
                  <path
                    d="M12 22s-8-4.5-8-11.8A8 8 0 0 1 12 2a8 8 0 0 1 8 8.2c0 7.3-8 11.8-8 11.8z"
                  />
                  <circle cx="12" cy="10" r="3" />
                </svg>
                {{ appData.position.facility }}
              </span>
              <span
                v-if="appData.position && appData.position.district"
                class="har-hero__meta-item"
              >
                <svg
                  width="11"
                  height="11"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                >
                  <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" />
                  <circle cx="12" cy="10" r="3" />
                </svg>
                {{ appData.position.district }}
              </span>
              <span
                v-if="appData.position && appData.position.grade"
                class="har-hero__meta-item"
              >
                <svg
                  width="11"
                  height="11"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                >
                  <polygon
                    points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"
                  />
                </svg>
                {{ appData.position.grade }}
              </span>
            </div>
            <div class="har-hero__chips">
              <span
                class="har-status"
                :class="'har-status--' + appData.statusCode"
              >
                <span class="har-status__dot"></span>
                {{ appData.statusDisplay }}
              </span>
            </div>
          </div>
          <div class="har-hero__right">
            <v-btn text dark small @click="goBack">
              <v-icon left small>mdi-arrow-left</v-icon>Back to Applicants
            </v-btn>
            <div class="har-info-card">
              <div class="har-info-card__label">Applied</div>
              <div class="har-info-card__val">
                {{ fmtDate(appData.applicationDate) }}
              </div>
              <div class="har-info-card__sep"></div>
              <div class="har-info-card__label">Reference</div>
              <div class="har-info-card__val har-info-card__val--mono">
                {{ appData.id }}
              </div>
            </div>
          </div>
        </div>
      </header>

      <!-- ── BODY ───────────────────────────────────────────────────── -->
      <div class="har-body">
        <!-- ── SECTION 1: Position & Advertisement ───────────────────── -->
        <v-card outlined class="mb-5">
          <v-card-title
            class="primary darken-1 white--text text-uppercase font-weight-bold"
          >
            Position &amp; Advertisement Details
          </v-card-title>
          <v-card-text class="my-3">
            <div class="har-two-col">
              <!-- LEFT: metadata fields -->
              <div class="har-two-col__left">
                <template v-if="appData.advert">
                  <div class="har-two-col__section-label">Advertisement</div>
                  <v-row dense>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Open Date</div>
                      <div class="har-value">
                        {{ fmtDate(appData.advert.openDate) }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Closing Date</div>
                      <div class="har-value">
                        {{ fmtDate(appData.advert.closeDate) }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Vacancies</div>
                      <div class="har-value">
                        {{
                          appData.advert.vacancies != null
                            ? appData.advert.vacancies
                            : "—"
                        }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Employment Category</div>
                      <div class="har-value">
                        {{
                          (appData.advert.employmentCategory &&
                            appData.advert.employmentCategory.display) ||
                            "—"
                        }}
                      </div>
                    </v-col>
                    <v-col v-if="appData.advert.employmentEnd" cols="12" sm="6">
                      <div class="har-label">Employment End Date</div>
                      <div class="har-value">
                        {{ fmtDate(appData.advert.employmentEnd) }}
                      </div>
                    </v-col>
                  </v-row>
                </template>

                <div
                  v-if="appData.advert && appData.position"
                  class="har-two-col__divider"
                ></div>

                <template v-if="appData.position">
                  <div class="har-two-col__section-label">Position</div>
                  <v-row dense>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Position Title</div>
                      <div class="har-value">
                        {{ appData.position.title || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Position Code</div>
                      <div class="har-value har-value--mono">
                        {{ appData.position.code || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Designation</div>
                      <div class="har-value">
                        {{ appData.position.designation || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Department</div>
                      <div class="har-value">
                        {{ appData.position.department || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Facility</div>
                      <div class="har-value">
                        {{ appData.position.facility || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">District</div>
                      <div class="har-value">
                        {{ appData.position.district || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Salary Grade</div>
                      <div class="har-value">
                        {{ appData.position.grade || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="har-label">Approved Posts</div>
                      <div class="har-value">
                        {{ appData.position.maxPosts || "—" }}
                      </div>
                    </v-col>
                  </v-row>
                </template>
              </div>

              <!-- RIGHT: long-form text fields -->
              <div class="har-two-col__right">
                <div class="har-two-col__section-label">
                  Descriptions &amp; Requirements
                </div>
                <div
                  v-if="
                    !(appData.advert && appData.advert.description) &&
                      !(appData.position && appData.position.description) &&
                      !(
                        appData.position && appData.position.minimumRequirements
                      ) &&
                      !(
                        appData.position &&
                        appData.position.additionalRequirements
                      )
                  "
                  class="har-two-col__empty"
                >
                  No descriptions or requirements recorded.
                </div>
                <template v-else>
                  <div
                    v-if="appData.advert && appData.advert.description"
                    class="har-desc-block"
                  >
                    <div class="har-desc-block__label">
                      Advertisement Description
                    </div>
                    <p class="har-desc-block__text">
                      {{ appData.advert.description }}
                    </p>
                  </div>
                  <div
                    v-if="appData.position && appData.position.description"
                    class="har-desc-block"
                  >
                    <div class="har-desc-block__label">
                      Position Description
                    </div>
                    <p class="har-desc-block__text">
                      {{ appData.position.description }}
                    </p>
                  </div>
                  <div
                    v-if="
                      appData.position && appData.position.minimumRequirements
                    "
                    class="har-desc-block"
                  >
                    <div class="har-desc-block__label">
                      Minimum Requirements
                    </div>
                    <p class="har-desc-block__text">
                      {{ appData.position.minimumRequirements }}
                    </p>
                  </div>
                  <div
                    v-if="
                      appData.position &&
                        appData.position.additionalRequirements
                    "
                    class="har-desc-block"
                  >
                    <div class="har-desc-block__label">
                      Additional Requirements
                    </div>
                    <p class="har-desc-block__text">
                      {{ appData.position.additionalRequirements }}
                    </p>
                  </div>
                </template>
              </div>
            </div>
          </v-card-text>
        </v-card>

        <!-- ── SECTION 2: Position Specification ───────────────────────── -->
        <v-card v-if="positionResource" outlined class="mb-5">
          <v-card-title class="primary darken-1 white--text text-uppercase font-weight-bold">
            Position Specification
          </v-card-title>
          <v-card-text class="pt-4">
            <position-specification :resource="positionResource" />
          </v-card-text>
        </v-card>

        <!-- ── SECTION 3: Applicant Profile (Tabs) ───────────────────── -->
        <v-card outlined class="mb-5">
          <v-card-title
            class="primary darken-1 white--text text-uppercase font-weight-bold"
          >
            Applicant Profile
          </v-card-title>

          <div v-if="profileLoading" class="d-flex align-center pa-5" style="gap:12px;">
            <v-progress-circular size="16" width="2" indeterminate color="teal darken-1" />
            <span class="caption grey--text">Loading applicant profile…</span>
          </div>

          <template v-else-if="appData && appData.practitionerRef">
            <internal-applicant-profile
              :practitioner-id="appData.practitionerRef.split('/')[1]"
            />
          </template>

          <div v-else-if="!profile" class="d-flex flex-column align-center pa-10 text-center" style="gap:10px;">
            <v-icon size="32" color="grey lighten-2">mdi-account-off-outline</v-icon>
            <div class="body-2 grey--text">Applicant profile could not be loaded.</div>
          </div>

          <template v-else>
            <external-applicant-profile :profile="profile" />
          </template>
        </v-card>

        <!-- ── SECTION 3b: Attachments ───────────────────────────────────── -->
        <v-card outlined class="mb-5">
          <v-card-title
            class="primary darken-1 white--text text-uppercase font-weight-bold"
          >
            Attachments
          </v-card-title>
          <v-card-text class="my-3">
            <application-attachments :attachments="appData.attachments" />
          </v-card-text>
        </v-card>

        <!-- ── SECTION 4: Matching Analysis ─────────────────────────────── -->
        <v-card v-if="appData.scoreData && appData.scoreData.score != null" outlined class="mb-5">
          <v-card-title class="primary darken-1 white--text text-uppercase font-weight-bold d-flex align-center justify-space-between">
            <span>Matching Analysis</span>
            <v-chip small dark :color="scoreBandColor(appData.scoreData.score)">
              {{ appData.scoreData.score }}% — {{ appData.scoreData.label }}
            </v-chip>
          </v-card-title>
          <v-card-text class="pt-3">
            <v-alert dense text type="info" icon="mdi-information-outline" class="mb-3">
              This is a system-generated suggestion based on the position specifications.
              HR retains full authority to shortlist or not shortlist.
            </v-alert>

            <div class="caption grey--text mb-1">
              Analysed on {{ appData.scoreData.analysedDate || "—" }}
            </div>

            <!-- Per-pathway breakdown -->
            <div v-if="appData.scoreData.breakdown && appData.scoreData.breakdown.length">
              <v-expansion-panels flat>
                <v-expansion-panel
                  v-for="(pathway, pi) in appData.scoreData.breakdown"
                  :key="pi"
                  class="mb-1"
                  style="border:1px solid #e7e5e4; border-radius:8px !important;"
                >
                  <v-expansion-panel-header class="py-2">
                    <div class="d-flex align-center" style="gap:10px;">
                      <v-chip x-small dark :color="scoreBandColor(pathway.score)">{{ pathway.score }}%</v-chip>
                      <span class="body-2 font-weight-bold">Pathway {{ pi + 1 }}</span>
                      <v-chip v-if="pathway.isBestMatch" x-small color="teal lighten-5" text-color="teal darken-2">Best Match</v-chip>
                      <span class="caption grey--text ml-auto">{{ pathway.metCriteria }}/{{ pathway.totalCriteria }} criteria met</span>
                    </div>
                  </v-expansion-panel-header>
                  <v-expansion-panel-content>
                    <v-list dense class="pa-0">
                      <v-list-item
                        v-for="(crit, ci) in pathway.criteriaResults"
                        :key="ci"
                        class="px-0"
                      >
                        <v-list-item-icon class="mr-2 my-auto">
                          <v-icon small :color="crit.met ? 'success' : 'error'">
                            {{ crit.met ? 'mdi-check-circle' : 'mdi-close-circle' }}
                          </v-icon>
                        </v-list-item-icon>
                        <v-list-item-content>
                          <v-list-item-subtitle>
                            <v-chip x-small class="mr-1" :color="crit.type === 'qualification' ? 'indigo lighten-5' : 'teal lighten-5'"
                              :text-color="crit.type === 'qualification' ? 'indigo darken-2' : 'teal darken-2'">
                              {{ crit.type }}
                            </v-chip>
                            {{ crit.detail }}
                          </v-list-item-subtitle>
                        </v-list-item-content>
                      </v-list-item>
                    </v-list>
                  </v-expansion-panel-content>
                </v-expansion-panel>
              </v-expansion-panels>
            </div>
          </v-card-text>
        </v-card>

        <!-- ── SECTION 5: HR Decision ─────────────────────────────────── -->
        <v-card outlined class="mb-5">
          <v-card-title
            class="primary darken-1 white--text text-uppercase font-weight-bold d-flex align-center justify-space-between"
          >
            <span>HR Decision</span>
            <span
              class="har-status har-status--sm"
              :class="'har-status--' + currentStatus"
            >
              <span class="har-status__dot"></span>
              {{ currentStatusDisplay }}
            </span>
          </v-card-title>
          <v-card-text class="pt-4">
            <!-- Decision history (newest first) -->
            <div
              v-if="applicationDecisions.length"
              class="har-decision-history"
            >
              <div class="har-decision-history__header">
                <v-icon size="13" color="#0369a1">mdi-clock-outline</v-icon>
                Decision History ({{ applicationDecisions.length }})
              </div>
              <div class="har-decision-history__list">
                <div
                  v-for="(dec, i) in applicationDecisions"
                  :key="i"
                  class="har-decision-entry"
                  :class="{ 'har-decision-entry--latest': i === 0 }"
                >
                  <div class="har-decision-entry__line"></div>
                  <div
                    class="har-decision-entry__dot"
                    :class="
                      'har-decision-entry__dot--' +
                        (dec.decisionType && dec.decisionType.code)
                    "
                  ></div>
                  <div class="har-decision-entry__content">
                    <div class="har-decision-entry__top">
                      <span
                        class="har-status har-status--sm"
                        :class="
                          'har-status--' +
                            (dec.decisionType && dec.decisionType.code)
                        "
                      >
                        <span class="har-status__dot"></span>
                        {{
                          (dec.decisionType && dec.decisionType.display) || "—"
                        }}
                      </span>
                      <span v-if="i === 0" class="har-decision-entry__badge"
                        >Latest</span
                      >
                      <span class="har-decision-entry__date">{{
                        fmtDate(dec.decisionDate)
                      }}</span>
                    </div>
                    <div v-if="dec.userName" class="har-decision-entry__user">
                      <v-icon size="11">mdi-account-outline</v-icon>
                      {{ dec.userName }}
                    </div>
                    <div class="har-decision-entry__reason">
                      {{ dec.decisionReason || "—" }}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <!-- Already in a terminal state -->
            <div v-if="isTerminalStatus" class="d-flex flex-column align-center pa-8 text-center" style="gap:10px;">
              <v-icon size="40" color="grey lighten-1">mdi-check-circle-outline</v-icon>
              <div class="subtitle-1 font-weight-bold grey--text text--darken-1">Decision finalised</div>
              <div class="body-2 grey--text" style="max-width:420px;">
                This application is marked as <strong>{{ currentStatusDisplay }}</strong>. No further action is required.
              </div>
            </div>

            <!-- underreview → shortlist / not shortlist -->
            <div v-else-if="currentStatus === 'underreview'">
              <v-alert v-if="hiringClosed" dense text type="error" class="mb-3">
                Hiring is closed for this advertisement. This applicant can no longer be shortlisted.
              </v-alert>

              <!-- Shortlist cap indicator -->
              <v-alert dense text :type="isShortlistCapReached ? 'warning' : 'info'" class="mb-0">
                <span v-if="isShortlistCapReached">
                  Shortlist cap reached — <strong>{{ totalShortlists }} / {{ shortlistCap }}</strong>
                  shortlists used ({{ (appData.advert && appData.advert.vacancies) || 1 }}
                  post{{ ((appData.advert && appData.advert.vacancies) || 1) !== 1 ? "s" : "" }}
                  × {{ maxShortlistsPerPost }} per post). No further shortlisting is allowed.
                </span>
                <span v-else>
                  Shortlists: <strong>{{ totalShortlists }} / {{ shortlistCap }}</strong>
                  ({{ (appData.advert && appData.advert.vacancies) || 1 }}
                  post{{ ((appData.advert && appData.advert.vacancies) || 1) !== 1 ? "s" : "" }}
                  × {{ maxShortlistsPerPost }} per post)
                </span>
              </v-alert>

              <p class="body-2 grey--text text--darken-1 mt-3">
                Review this application and decide whether to shortlist the applicant for interview.
              </p>
              <v-textarea v-model="decisionReason" label="Reason / Notes (required)" outlined dense rows="3" class="mt-3"
                :error-messages="reasonError ? ['Please provide a reason before proceeding.'] : []" />
              <div class="d-flex flex-wrap mt-2" style="gap:12px;">
                <v-btn color="success" depressed :disabled="saving || isShortlistCapReached || hiringClosed" @click="requestDecision('shortlisted')">
                  <v-icon left small>mdi-check</v-icon>Shortlist for Interview
                </v-btn>
                <v-btn color="error" depressed :disabled="saving" @click="requestDecision('notshortlisted')">
                  <v-icon left small>mdi-close</v-icon>Do Not Shortlist
                </v-btn>
              </div>
            </div>

            <!-- shortlisted → offer / not offer -->
            <div v-else-if="currentStatus === 'shortlisted'">
              <p class="body-2 grey--text text--darken-1">
                This applicant has been shortlisted. Decide whether to make a formal job offer.
              </p>
              <v-alert v-if="hiringClosed" dense text type="error" class="mb-2">
                Hiring is closed for this advertisement. A job offer can no longer be made to this applicant.
              </v-alert>
              <!-- Offer cap banner -->
              <v-alert v-if="isOfferCapReached" dense text type="warning" class="mb-2">
                All <strong>{{ appData.advert.vacancies }}</strong> position{{ appData.advert.vacancies !== 1 ? "s" : "" }}
                for this vacancy have already been filled ({{ totalOffered }} offer{{ totalOffered !== 1 ? "s" : "" }} made).
                No further offers can be issued.
              </v-alert>
              <v-row dense class="mt-3">
                <v-col cols="12" sm="6">
                  <v-textarea
                    v-model="decisionReason"
                    label="Reason / Notes (required)"
                    outlined
                    dense
                    rows="3"
                    :error-messages="
                      reasonError
                        ? ['Please provide a reason before proceeding.']
                        : []
                    "
                  ></v-textarea>
                </v-col>
                <v-col cols="12" sm="6">
                  <v-menu
                    v-model="jobStartDateMenu"
                    :close-on-content-click="false"
                    offset-y
                    max-width="290"
                  >
                    <template v-slot:activator="{ on }">
                      <v-text-field
                        :value="jobStartDate ? fmtDate(jobStartDate) : ''"
                        label="Official Start Date (required for job offer)"
                        outlined
                        dense
                        readonly
                        clearable
                        prepend-inner-icon="mdi-calendar-check"
                        :error-messages="
                          startDateError
                            ? ['Please select the official start date.']
                            : startDateBeforeOpenError
                            ? [
                                'Start date cannot be before the advertisement open date (' +
                                  fmtDate(appData.advert.openDate) +
                                  ').',
                              ]
                            : startDateAfterEndError
                            ? [
                                'Start date cannot be after the employment end date (' +
                                  fmtDate(appData.advert.employmentEnd) +
                                  ').',
                              ]
                            : []
                        "
                        v-on="on"
                        @click:clear="
                          jobStartDate = null;
                          startDateBeforeOpenError = false;
                          startDateAfterEndError = false;
                        "
                      />
                    </template>
                    <v-date-picker
                      v-model="jobStartDate"
                      no-title
                      scrollable
                      :min="
                        (appData.advert && appData.advert.openDate) || undefined
                      "
                      :max="
                        (appData.advert && appData.advert.employmentEnd) ||
                          undefined
                      "
                      @input="
                        jobStartDateMenu = false;
                        startDateError = false;
                        startDateBeforeOpenError = false;
                        startDateAfterEndError = false;
                      "
                    />
                  </v-menu>
                  <!-- Contract duration preview -->
                  <v-alert v-if="contractDuration" dense text type="info" icon="mdi-clock-outline" class="mt-2 mb-0">
                    Contract duration: <strong>{{ contractDuration }}</strong>
                  </v-alert>
                </v-col>
                <v-col cols="12">
                  <div class="caption font-weight-bold mb-1">
                    Supervisor <span class="error--text">*</span>
                  </div>
                  <div
                    class="har-sup-trigger"
                    :class="{
                      'har-sup-trigger--filled': !!supervisor.reference,
                      'har-sup-trigger--error': supervisorError,
                    }"
                    @click="openSupervisorDialog"
                  >
                    <template v-if="supervisor.reference">
                      <v-avatar size="28" color="purple lighten-4" class="mr-2">
                        <span
                          class="caption indigo--text text--darken-3 font-weight-bold"
                          >{{ getInitials(supervisor.display) }}</span
                        >
                      </v-avatar>
                      <div style="flex:1;min-width:0;">
                        <div class="har-sup-trigger__name">
                          {{ supervisor.display }}
                        </div>
                        <div class="har-sup-trigger__meta">
                          <span v-if="supervisor.position">{{
                            supervisor.position
                          }}</span>
                          <span
                            v-if="supervisor.position && supervisor.facility"
                          >
                            ·
                          </span>
                          <span v-if="supervisor.facility">{{
                            supervisor.facility
                          }}</span>
                        </div>
                      </div>
                      <v-btn
                        icon
                        x-small
                        @click.stop="clearSupervisor"
                        style="margin-left:auto;"
                      >
                        <v-icon small color="#a8a29e">mdi-close</v-icon>
                      </v-btn>
                    </template>
                    <template v-else>
                      <v-icon color="#a8a29e" class="mr-2"
                        >mdi-account-search-outline</v-icon
                      >
                      <span class="har-sup-trigger__placeholder"
                        >Click to search and select a supervisor…</span
                      >
                    </template>
                  </div>
                  <div v-if="supervisorError" class="error--text caption mt-1">Please select a supervisor.</div>
                </v-col>
                <v-col cols="12" sm="6">
                  <div class="caption font-weight-bold mb-1">
                    Salary Notch <span class="error--text">*</span>
                    <span v-if="appData.position && appData.position.grade" class="grey--text font-weight-regular ml-1">(Grade: {{ appData.position.grade }})</span>
                  </div>
                  <v-autocomplete
                    v-model="salaryNotch"
                    :items="notchItems"
                    item-text="text"
                    item-value="value"
                    outlined
                    dense
                    :loading="loadingNotches"
                    :disabled="loadingNotches"
                    placeholder="Select a notch…"
                    clearable
                    :error-messages="
                      notchError ? ['Please select a salary notch.'] : []
                    "
                    @change="notchError = false"
                  />
                </v-col>
                <template v-if="isInternalApplicant">
                  <v-col cols="12" sm="6">
                    <div class="caption font-weight-bold mb-1">
                      Is Head of Department
                    </div>
                    <v-select
                      v-model="isHOD"
                      :items="yesNoOptions"
                      item-text="display"
                      outlined
                      dense
                      return-object
                      clearable
                      placeholder="Select…"
                      prepend-inner-icon="mdi-account-star"
                      @change="onHodChange"
                    />
                  </v-col>

                  <!-- HOD Level (district or facility) -->
                  <v-col cols="12" sm="6" v-if="isHOD && isHOD.code === 'yes'">
                    <div class="caption font-weight-bold mb-1">HOD Level</div>
                    <v-select
                      v-model="hodType"
                      :items="[
                        { text: 'District', value: 'district' },
                        { text: 'Facility', value: 'facility' },
                      ]"
                      item-text="text"
                      item-value="value"
                      outlined
                      dense
                      clearable
                      prepend-inner-icon="mdi-map-marker-radius"
                      @change="onHodTypeChange"
                    />
                  </v-col>

                  <!-- HOD location treeview (shown when hodType is set) -->
                  <v-col
                    cols="12"
                    sm="6"
                    v-if="isHOD && isHOD.code === 'yes' && hodType"
                  >
                    <div class="caption font-weight-bold mb-1">
                      {{ hodType === "district" ? "District" : "Facility" }}
                    </div>
                    <v-menu
                      v-model="hodTreeOpen"
                      :close-on-content-click="false"
                      offset-y
                      min-width="320px"
                    >
                      <template v-slot:activator="{ on }">
                        <v-text-field
                          :value="hodTree.displayValue"
                          dense
                          outlined
                          clearable
                          hide-details
                          readonly
                          :prepend-inner-icon="
                            hodType === 'district'
                              ? 'mdi-map-marker'
                              : 'mdi-hospital-building'
                          "
                          v-on="on"
                          @click:clear="clearHodTree"
                        />
                      </template>
                      <v-card>
                        <v-treeview
                          :active.sync="hodTree.active"
                          :items="hodTree.items"
                          :load-children="fetchHodChildren"
                          :open.sync="hodTree.open"
                          item-disabled="locked"
                          activatable
                          :multiple-active="false"
                          selection-type="independent"
                          :loading="hodTree.loading"
                          item-key="id"
                          dense
                          hoverable
                          open-on-click
                          style="max-height:280px;overflow-y:auto;"
                        >
                          <template v-slot:label="{ item }">
                            <span style="font-size:13px;">{{
                              item.name
                            }}</span>
                          </template>
                        </v-treeview>
                      </v-card>
                    </v-menu>
                  </v-col>

                  <!-- HOD summary banner -->
                  <v-col cols="12" v-if="hodSummary">
                    <v-alert
                      dense
                      outlined
                      color="indigo"
                      icon="mdi-account-star"
                      class="mb-0"
                    >
                      {{ hodSummary }}
                    </v-alert>
                  </v-col>

                  <v-col cols="12" sm="6">
                    <div class="caption font-weight-bold mb-1">
                      Is Departmental Director
                    </div>
                    <v-select
                      v-model="isDepartmentalDirector"
                      :items="yesNoOptions"
                      item-text="display"
                      outlined
                      dense
                      return-object
                      clearable
                      placeholder="Select…"
                      prepend-inner-icon="mdi-account-tie"
                    />
                  </v-col>
                </template>
              </v-row>
              <div class="d-flex flex-wrap mt-2" style="gap:12px;">
                <v-btn color="success" depressed :disabled="saving || isOfferCapReached || hiringClosed" @click="requestDecision('offered')">
                  <v-icon left small>mdi-check</v-icon>Offer Job
                </v-btn>
                <v-btn color="error" depressed :disabled="saving" @click="requestDecision('notrecommended')">
                  <v-icon left small>mdi-close</v-icon>Do Not Offer Job
                </v-btn>
              </div>
            </div>

            <!-- saving indicator -->
            <v-progress-linear
              v-if="saving"
              indeterminate
              color="#0d9488"
              height="3"
              class="mt-3"
            ></v-progress-linear>

            <!-- feedback alerts -->
            <v-alert
              v-if="saveSuccess"
              type="success"
              dense
              text
              border="left"
              class="mt-3"
            >
              Decision saved successfully. Status is now
              <strong>{{ currentStatusDisplay }}</strong
              >.
            </v-alert>
            <v-alert
              v-if="saveError"
              type="error"
              dense
              text
              border="left"
              class="mt-3"
            >
              {{ saveError }}
            </v-alert>
          </v-card-text>
        </v-card>
      </div>
    </template>
  </div>
</template>

<script>
import ExternalApplicantProfile from "./ExternalApplicantProfile.vue";
import InternalApplicantProfile from "./InternalApplicantProfile.vue";
import PositionSpecification from "../shared/PositionSpecification.vue";
import ApplicationAttachments from "../shared/ApplicationAttachments.vue";

export default {
  name: "HrApplicationReview",
  components: {
    ExternalApplicantProfile,
    InternalApplicantProfile,
    PositionSpecification,
    ApplicationAttachments,
  },
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,
      appData: null,
      positionResource: null,

      profile: null,
      profileLoading: false,

      currentStatus: "underreview",
      currentStatusDisplay: "Under Review",
      applicationDecisions: [],

      decisionReason: "",
      totalShortlists: 0,
      totalOffered: 0,
      // Change this number to adjust the max shortlists allowed per advertised post
      maxShortlistsPerPost: 3,
      reasonError: false,
      jobStartDate: null,
      jobStartDateMenu: false,
      startDateError: false,
      startDateBeforeOpenError: false,
      startDateAfterEndError: false,
      saving: false,
      saveSuccess: false,
      saveError: null,

      confirmDialog: false,
      confirmAction: null,
      confirmTitle: "",
      confirmMessage: "",
      confirmBtnLabel: "",
      confirmDanger: false,

      salaryNotch: null,
      notchItems: [],
      loadingNotches: false,
      notchError: false,

      isHOD: null,
      isDepartmentalDirector: null,
      yesNoOptions: [],
      hodType: null,
      hodTreeOpen: false,
      hodTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {}, // 'Location/id' → { name, type: 'district'|'council'|'facility' }
        loading: false,
        displayValue: "",
      },

      supervisor: {
        reference: null,
        display: "",
        position: "",
        facility: "",
        grade: "",
      },
      supervisorError: false,
      supervisorDialog: false,
      supervisorItems: [],
      supervisorTotal: 0,
      loadingSupervisors: false,
      supervisorOptions: { page: 1, itemsPerPage: 10 },
      supFilter: { name: "", position: "", department: null },
      supDebounce: null,
      supFilterTreeOpen: false,
      filterTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {},
        loading: false,
        displayValue: "",
      },
      departmentOptions: [],
      supervisorHeaders: [
        { text: "Name", value: "name", sortable: false },
        { text: "Position", value: "position", sortable: false },
        { text: "Department", value: "department", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        { text: "Grade", value: "grade", sortable: false },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 90,
        },
      ],
    };
  },

  computed: {
    applicationId() {
      return this.queries?.applicationId || null;
    },

    isInternalApplicant() {
      return !!this.appData?.practitionerRef;
    },

    hiringClosed() {
      return this.appData?.advert?.hiringStatus?.code === "closed";
    },

    isTerminalStatus() {
      return [
        "notshortlisted",
        "offered",
        "notrecommended",
        "interviewed",
        "recommended",
        "accepted",
        "declined",
        "withdrawn",
      ].includes(this.currentStatus);
    },

    shortlistCap() {
      const posts = this.appData?.advert?.vacancies || 1;
      return posts * this.maxShortlistsPerPost;
    },

    isShortlistCapReached() {
      return this.totalShortlists >= this.shortlistCap;
    },

    isOfferCapReached() {
      const vacancies = this.appData?.advert?.vacancies || 1;
      return this.totalOffered >= vacancies;
    },

    contractDuration() {
      const empEnd = this.appData?.advert?.employmentEnd;
      if (!this.jobStartDate || !empEnd) return null;
      const start = new Date(this.jobStartDate);
      const end = new Date(empEnd);
      if (start >= end) return null;
      let years = end.getFullYear() - start.getFullYear();
      let months = end.getMonth() - start.getMonth();
      if (months < 0) {
        years--;
        months += 12;
      }
      const parts = [];
      if (years > 0) parts.push(`${years} year${years !== 1 ? "s" : ""}`);
      if (months > 0) parts.push(`${months} month${months !== 1 ? "s" : ""}`);
      return parts.length ? parts.join(", ") : "Less than a month";
    },
    hodSummary() {
      if (this.isHOD?.code !== "yes") return null;
      const dept = this.appData?.position?.department;
      if (!dept || !this.hodTree.active.length) return null;
      const id = this.hodTree.active[0];
      const info = this.hodTree.treeLookup[id];
      if (!info) return null;
      if (this.hodType === "district") {
        return `This staff will be Head of ${dept} Department at ${info.name} District`;
      }
      if (this.hodType === "facility" && info.type === "facility") {
        return `This staff will be Head of ${dept} Department at ${info.name}`;
      }
      return null;
    },
  },

  watch: {
    "filterTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.filterTree.displayValue = id
        ? this.filterTree.treeLookup[id]?.name || id
        : "";
      this.supervisorOptions.page = 1;
      this.fetchSupervisors();
    },
    supervisorOptions: {
      deep: true,
      handler() {
        if (this.supervisorDialog) this.fetchSupervisors();
      },
    },
    "hodTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.hodTree.displayValue = id
        ? this.hodTree.treeLookup[id]?.name || id
        : "";
    },
  },

  async mounted() {
    if (!this.applicationId) {
      this.error = "No application ID provided.";
      this.loading = false;
      return;
    }
    await this.loadApplication();
    this.loadCounts();
  },

  methods: {
    async loadApplication() {
      this.loading = true;
      this.error = null;
      try {
        const res = await fetch(
          `/site/position/application/${this.applicationId}`,
        );
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        this.appData = await res.json();
        this.currentStatus = this.appData.statusCode || "underreview";
        this.currentStatusDisplay =
          this.appData.statusDisplay || "Under Review";
        this.applicationDecisions = this.appData.applicationDecisions || [];
        await this.loadProfile();
        this.loadPositionResource();
        if (this.currentStatus === "shortlisted") {
          this.loadNotchesForGrade();
          if (this.isInternalApplicant) this.loadYesNoOptions();
        }
      } catch (err) {
        console.error("loadApplication error", err);
        this.error = err.message || "Failed to load application.";
      } finally {
        this.loading = false;
      }
    },

    async loadPositionResource() {
      const posId = this.appData?.position?.id;
      if (!posId) return;
      try {
        const res = await fetch(`/fhir/Basic/${posId}`);
        if (res.ok) this.positionResource = await res.json();
      } catch (_) { /* non-critical */ }
    },

    async loadProfile() {
      if (this.appData?.practitionerRef) return;
      const ref = this.appData?.applicantRef;
      if (!ref) return;
      this.profileLoading = true;
      try {
        const id = ref.split("/")[1];
        const res = await fetch(`/fhir/Basic/${id}`);
        if (res.ok) this.profile = await res.json();
      } catch (e) {
        console.error("loadProfile error", e);
      } finally {
        this.profileLoading = false;
      }
    },

    openSupervisorDialog() {
      this.supervisorDialog = true;
      this.loadFilterTree();
      this.loadDepartmentOptions();
      this.fetchSupervisors();
    },

    debouncedFetchSupervisors() {
      clearTimeout(this.supDebounce);
      this.supDebounce = setTimeout(() => {
        this.supervisorOptions.page = 1;
        this.fetchSupervisors();
      }, 350);
    },

    async fetchSupervisors() {
      this.loadingSupervisors = true;
      try {
        const params = new URLSearchParams({
          page: this.supervisorOptions.page,
          count: this.supervisorOptions.itemsPerPage,
        });
        if (this.supFilter.name) params.set("name", this.supFilter.name);
        if (this.supFilter.position)
          params.set("position", this.supFilter.position);
        if (this.supFilter.department)
          params.set("department", this.supFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }
        const res = await fetch(`/site/position/supervisors?${params}`);
        const data = await res.json();
        this.supervisorTotal = data.total || 0;
        this.supervisorItems = data.supervisors || [];
      } catch (err) {
        console.error("fetchSupervisors error", err);
      } finally {
        this.loadingSupervisors = false;
      }
    },

    selectSupervisor(item) {
      this.supervisor = {
        reference: item.practitionerRef,
        display: item.name,
        position: item.position || "",
        facility: item.facility || "",
        grade: item.grade || "",
      };
      this.supervisorError = false;
      this.supervisorDialog = false;
    },

    clearSupervisor() {
      this.supervisor = {
        reference: null,
        display: "",
        position: "",
        facility: "",
        grade: "",
      };
    },

    async loadNotchesForGrade() {
      const gradeRef = this.appData?.position?.gradeRef;
      if (!gradeRef || this.notchItems.length) return;
      this.loadingNotches = true;
      try {
        const NOTCH_PROFILE =
          "http://ihris.org/fhir/StructureDefinition/ls-salary-notch-profile";
        const res = await fetch(
          `/fhir/Basic?_profile=${NOTCH_PROFILE}&salarygrade=${gradeRef}&_count=200`,
        );
        const data = await res.json();
        const EXT_NOTCH = "http://ihris.org/fhir/StructureDefinition/notch";
        const EXT_AMOUNT =
          "http://ihris.org/fhir/StructureDefinition/ls-salary-amount";
        this.notchItems = (data.entry || []).map((e) => {
          const notchCoding = e.resource.extension?.find(
            (x) => x.url === EXT_NOTCH,
          )?.valueCoding;
          const amountExt = e.resource.extension?.find(
            (x) => x.url === EXT_AMOUNT,
          );
          const money = amountExt?.valueMoney;
          const amount = money
            ? `${money.currency} ${Number(money.value).toLocaleString()}`
            : "";
          const name = notchCoding
            ? notchCoding.display || notchCoding.code
            : e.resource.id;
          const label = amount ? `${name}  (${amount})` : name;
          return { value: `Basic/${e.resource.id}`, text: label };
        });
      } catch (err) {
        console.error("loadNotchesForGrade error", err);
      } finally {
        this.loadingNotches = false;
      }
    },

    async loadDepartmentOptions() {
      if (this.departmentOptions.length) return;
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/departments-valueset",
        );
        this.departmentOptions = (items || []).map((c) => ({
          code: c.code,
          display: c.display || c.code,
        }));
      } catch (err) {
        console.error("loadDepartmentOptions error", err);
      }
    },

    async loadYesNoOptions() {
      if (this.yesNoOptions.length) return;
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/yes-no-valueset",
        );
        this.yesNoOptions = (items || []).map((c) => ({
          system: c.system,
          code: c.code,
          display: c.display,
        }));
      } catch (err) {
        console.error("loadYesNoOptions error", err);
      }
    },

    // ── HOD handlers ───────────────────────────────────────────────────
    onHodChange() {
      if (this.isHOD?.code !== "yes") {
        this.hodType = null;
        this.clearHodTree();
      } else {
        this.loadHodTree();
      }
    },

    onHodTypeChange() {
      this.clearHodTree();
      this.loadHodTree();
    },

    async loadHodTree() {
      if (!this.hodType) return;
      this.hodTree.loading = true;
      this.hodTree.items = [];
      this.hodTree.treeLookup = {};
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const facilityMode = this.hodType === "facility";
        const nodes = (data.entry || []).map((e) => {
          const node = {
            id: "Location/" + e.resource.id,
            name: e.resource.name,
            locked: facilityMode, // districts not selectable in facility mode
          };
          if (facilityMode) node.children = []; // lazy-loadable in facility mode
          this.hodTree.treeLookup[node.id] = {
            name: node.name,
            type: "district",
          };
          return node;
        });
        this.hodTree.items = nodes;
      } catch (err) {
        console.error("loadHodTree error", err);
      } finally {
        this.hodTree.loading = false;
      }
    },

    fetchHodChildren(item) {
      const parentInfo = this.hodTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
              locked: childType !== "facility", // only facilities are selectable
            };
            if (childType === "council") node.children = []; // councils expand further
            this.hodTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchHodChildren error", err));
    },

    clearHodTree() {
      this.hodTree.active = [];
      this.hodTree.open = [];
      this.hodTree.displayValue = "";
      this.hodTree.items = [];
      this.hodTree.treeLookup = {};
    },

    async loadFilterTree() {
      if (this.filterTree.items.length) return;
      this.filterTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [],
        }));
        nodes.forEach((n) => {
          this.filterTree.treeLookup[n.id] = { name: n.name, type: "district" };
        });
        this.filterTree.items = nodes;
      } catch (err) {
        console.error("loadFilterTree error", err);
      } finally {
        this.filterTree.loading = false;
      }
    },

    async fetchFilterChildren(item) {
      const parentInfo = this.filterTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      try {
        const r = await fetch(`/fhir/Location?partof=${item.id}&_count=200`);
        const data = await r.json();
        const children = (data.entry || []).map((e) => {
          const node = {
            id: "Location/" + e.resource.id,
            name: e.resource.name,
          };
          if (childType === "council") node.children = [];
          this.filterTree.treeLookup[node.id] = {
            name: node.name,
            type: childType,
          };
          return node;
        });
        item.children.push(...children);
      } catch (err) {
        console.error("fetchFilterChildren error", err);
      }
    },

    clearFilterTree() {
      this.filterTree.active = [];
      this.filterTree.displayValue = "";
    },

    getInitials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .slice(0, 2)
        .map((w) => w[0])
        .join("")
        .toUpperCase();
    },

    requestDecision(statusCode) {
      if (
        this.hiringClosed &&
        (statusCode === "shortlisted" || statusCode === "offered")
      ) {
        return;
      }
      if (!this.decisionReason.trim()) {
        this.reasonError = true;
        return;
      }
      if (statusCode === "offered" && !this.jobStartDate) {
        this.startDateError = true;
        return;
      }
      if (statusCode === "offered" && this.jobStartDate) {
        const empEnd = this.appData?.advert?.employmentEnd;
        const openDate = this.appData?.advert?.openDate;
        if (openDate && this.jobStartDate < openDate) {
          this.startDateBeforeOpenError = true;
          return;
        }
        if (empEnd && this.jobStartDate > empEnd) {
          this.startDateAfterEndError = true;
          return;
        }
      }
      if (statusCode === "offered" && !this.salaryNotch) {
        this.notchError = true;
        return;
      }
      if (statusCode === "offered" && !this.supervisor.reference) {
        this.supervisorError = true;
        return;
      }
      const configs = {
        shortlisted: {
          title: "Shortlist for Interview",
          message:
            "Are you sure you want to shortlist this applicant for interview?",
          btnLabel: "Yes, Shortlist",
          danger: false,
        },
        notshortlisted: {
          title: "Do Not Shortlist",
          message:
            "Are you sure you do not want to shortlist this applicant? This action cannot be undone.",
          btnLabel: "Yes, Do Not Shortlist",
          danger: true,
        },
        offered: {
          title: "Offer Job",
          message:
            "Are you sure you want to make a formal job offer to this applicant?",
          btnLabel: "Yes, Offer Job",
          danger: false,
        },
        notrecommended: {
          title: "Do Not Offer Job",
          message:
            "Are you sure you do not want to offer this job to the applicant? This action cannot be undone.",
          btnLabel: "Yes, Do Not Offer",
          danger: true,
        },
      };
      const cfg = configs[statusCode];
      this.confirmAction = statusCode;
      this.confirmTitle = cfg.title;
      this.confirmMessage = cfg.message;
      this.confirmBtnLabel = cfg.btnLabel;
      this.confirmDanger = cfg.danger;
      this.confirmDialog = true;
    },

    confirmDecision() {
      this.confirmDialog = false;
      this.makeDecision(this.confirmAction);
    },

    async makeDecision(statusCode) {
      this.reasonError = false;
      this.startDateError = false;
      this.startDateBeforeOpenError = false;
      this.startDateAfterEndError = false;
      this.notchError = false;
      this.saving = true;
      this.saveSuccess = false;
      this.saveError = null;
      try {
        const payload = { statusCode, reason: this.decisionReason.trim() };
        if (statusCode === "offered") {
          payload.startDate = this.jobStartDate;
          payload.notch = this.salaryNotch;
          payload.supervisor = {
            reference: this.supervisor.reference,
            display: this.supervisor.display,
          };
          if (this.isInternalApplicant) {
            payload.isHOD = this.isHOD || null;
            payload.isDepartmentalDirector = this.isDepartmentalDirector || null;
            payload.hodType = this.hodType || null;
            payload.hodDistrictId =
              this.hodType === "district" && this.hodTree.active.length
                ? this.hodTree.active[0]
                : null;
            payload.hodFacilityId =
              this.hodType === "facility" && this.hodTree.active.length
                ? this.hodTree.active[0]
                : null;
          }
        }
        const res = await fetch(
          `/site/position/application/${this.applicationId}/status`,
          {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          },
        );
        const body = await res.json();
        if (!res.ok) throw new Error(body.error || `HTTP ${res.status}`);
        this.currentStatus = body.statusCode;
        this.currentStatusDisplay = body.statusDisplay;
        if (body.newDecision) {
          this.applicationDecisions = [
            body.newDecision,
            ...this.applicationDecisions,
          ];
        }
        if (body.statusCode === "shortlisted") {
          this.totalShortlists += 1;
          this.loadNotchesForGrade();
        }
        if (body.statusCode === "offered") {
          this.totalOffered += 1;
        }
        this.decisionReason = "";
        this.jobStartDate = null;
        this.salaryNotch = null;
        this.isHOD = null;
        this.isDepartmentalDirector = null;
        this.hodType = null;
        this.clearHodTree();
        this.clearSupervisor();
        this.saveSuccess = true;
      } catch (err) {
        console.error("makeDecision error", err);
        this.saveError = err.message || "Failed to save decision.";
      } finally {
        this.saving = false;
      }
    },

    async countShortlists() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/application-profile",
        advertisedvacancy: "Basic/" + this.queries.advertId,
        posappstatus: "shortlisted",
        _count: 0,
        _total: "accurate",
      });
      const res = await fetch(`/fhir/Basic?${params}`);
      const bundle = await res.json();
      return bundle.total || 0;
    },

    async countOffered() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/application-profile",
        advertisedvacancy: "Basic/" + this.queries.advertId,
        posappstatus: "offered",
        _count: 0,
        _total: "accurate",
      });
      const res = await fetch(`/fhir/Basic?${params}`);
      const bundle = await res.json();
      return bundle.total || 0;
    },

    async loadCounts() {
      try {
        const [shortlisted, offered] = await Promise.all([
          this.countShortlists(),
          this.countOffered(),
        ]);
        this.totalOffered = offered;
        this.totalShortlists = shortlisted + offered;
      } catch (err) {
        console.error("loadCounts error", err);
      }
    },

    // ── Score band color ─────────────────────────────────────────────
    scoreBandColor(score) {
      if (score >= 80) return "success";
      if (score >= 60) return "teal darken-1";
      if (score >= 40) return "orange darken-1";
      if (score >= 20) return "deep-orange";
      return "error";
    },

    // ── Navigation ───────────────────────────────────────────────────
    goBack() {
      const advertId = this.appData?.vacancyRef
        ? this.appData.vacancyRef.split("/")[1]
        : null;
      if (advertId) {
        this.$router.push({
          path: "/custom/applicant-list",
          query: { path: "/lesotho/components/recruitment", advertId },
        });
      } else {
        this.$router.push({
          path: "/custom/index",
          query: { path: "/lesotho/components/recruitment" },
        });
      }
    },

    // ── Date formatter ───────────────────────────────────────────────
    fmtDate(val) {
      if (!val) return "—";
      try {
        const [y, m, d] = val.split("T")[0].split("-");
        const months = [
          "Jan",
          "Feb",
          "Mar",
          "Apr",
          "May",
          "Jun",
          "Jul",
          "Aug",
          "Sep",
          "Oct",
          "Nov",
          "Dec",
        ];
        if (!m) return y;
        if (!d) return `${months[parseInt(m, 10) - 1]} ${y}`;
        return `${parseInt(d, 10)} ${months[parseInt(m, 10) - 1]} ${y}`;
      } catch {
        return val;
      }
    },
  },
};
</script>

